jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  function _exportEverything() {
    // Office Add-in / Script Lab iframes block <a download> writes
    // (Office.context.document.url is read-only). Clipboard is the
    // reliable path — user pastes into Notepad / VS Code / etc. and
    // saves as eli-backup-<stamp>.json. eli.backup.copyToClipboard()
    // wraps a textarea-fallback for when navigator.clipboard is
    // blocked (typical for sandboxed iframes).
    if (!window.eli.backup || typeof window.eli.backup.copyToClipboard !== "function") {
      if (typeof showToast === "function") showToast("Backup API missing — kernel reload needed.", "err");
      return;
    }
    var btn = document.querySelector("[data-refresh-act='export']");
    if (btn) { btn.disabled = true; btn.textContent = "⏳ Bundling…"; }
    eli.events.safeAsync(window.eli.backup.copyToClipboard(), "refresh_eli.export")
      .then(function () {
        if (typeof showToast === "function") {
          showToast("✅ Backup copied to clipboard — paste into a .json file and save it before wiping", "ok");
        }
        if (btn) { btn.disabled = false; btn.innerHTML = '<span class="_eli3_re_icon">📋</span> Copy backup to clipboard'; }
      })
      .catch(function (err) {
        if (typeof showToast === "function") showToast("Export failed: " + (err && err.message), "err");
        if (btn) { btn.disabled = false; btn.innerHTML = '<span class="_eli3_re_icon">📋</span> Copy backup to clipboard'; }
      });
  }

  function _wipeAndReload() {
    if (typeof showEliDialog !== "function") {
      if (typeof showToast === "function") showToast("Confirm dialog missing.", "err");
      return;
    }
    showEliDialog({
      variant: "danger",
      tier: "premium",
      icon: "⚠️",
      title: "Wipe everything?",
      body:
        '<div style="font:500 12.5px/1.5 \'Inter\',sans-serif; color:#0f172a;">' +
          'Clears every IDB store (stats, trophies, prompts, templates, tools, settings) ' +
          'AND every v2 localStorage key (user profile, API key, pinned apps, ' +
          'dashboard layout).<br><br>' +
          '<b style="color:#b91c1c;">If you haven\'t exported a backup, this is irreversible.</b><br><br>' +
          'After the wipe, the page reloads. ELI re-onboards from scratch. ' +
          'You can import your backup file afterward to restore the previous state.' +
        '</div>',
      primary: {
        label: "🗑 Wipe & Reload",
        cls: "btn-action",
        style: "flex:1; background:linear-gradient(135deg,#dc2626,#991b1b); color:#fff; border:none;",
        onclick: function () { _doWipe(); },
      },
      secondary: { label: "Cancel" },
    });
  }

  function _doWipe() {
    // Wipe scope = STORES_TO_WIPE (backup + tools). Tools intentionally
    // skipped by exportAll but cleared here so the post-reload state
    // truly looks first-run — tools re-download from CDN on next sync.
    // Fallback to STORES_TO_BACKUP for older kernels that pre-date the
    // split (won't clear tools, but won't crash).
    var stores =
      (window.eli.backup && window.eli.backup.STORES_TO_WIPE) ||
      (window.eli.backup && window.eli.backup.STORES_TO_BACKUP) ||
      [];
    if (typeof showToast === "function") showToast("Wiping…", "info");
    var ops = stores.map(function (store) {
      return window.eli.storage.clearStore(store).catch(function () {});
    });
    return Promise.all(ops).then(function () {
      // Drop every v2 localStorage key the audit set tracks. Also wipe
      // ELI's own debug + zoom + agreement-data + pending-update keys
      // so the post-reload state truly looks first-run.
      var keys = (window.eli.compat && window.eli.compat.v2Keys) || [];
      keys.forEach(function (k) {
        try { window.eli.compat.lsRemove(k); } catch (e) { /* tolerate */ }
      });
      // Belt-and-suspenders: scan localStorage for any eli_* keys the
      // audit list might have missed (legacy keys, per-section stamps,
      // force-enable one-shots) and remove them too.
      try {
        var stragglers = [];
        for (var i = 0; i < localStorage.length; i++) {
          var k = localStorage.key(i);
          if (k && (k.indexOf("eli_") === 0 || k.indexOf("ELI_") === 0 || k.indexOf("_eli3_") === 0)) {
            stragglers.push(k);
          }
        }
        stragglers.forEach(function (k) { localStorage.removeItem(k); });
      } catch (e) { /* tolerate iframe restrictions */ }
      // Wipe Office document-level cache too (EliEmailerPrefill,
      // eli_version_history, AgreementDataDetails, etc.).
      try {
        if (typeof Office !== "undefined" && Office.context && Office.context.document && Office.context.document.settings) {
          var docSettings = Office.context.document.settings;
          ["EliEmailerPrefill", "eli_version_history", "AgreementDataDetails"].forEach(function (k) {
            try { docSettings.remove(k); } catch (e) {}
          });
          docSettings.saveAsync(function () { /* fire-and-forget */ });
        }
      } catch (e) { /* tolerate */ }
      eli.log.event("refresh_eli", "wiped", { stores: stores.length });
      setTimeout(function () { location.reload(); }, 600);
    });
  }

  function _importBackup() {
    var input = document.createElement("input");
    input.type = "file";
    input.accept = ".json,application/json";
    input.style.display = "none";
    input.onchange = function () {
      var f = input.files && input.files[0];
      if (!f) return;
      var reader = new FileReader();
      reader.onload = function () {
        var text = reader.result;
        var parsed;
        try { parsed = JSON.parse(text); }
        catch (e) {
          if (typeof showToast === "function") showToast("Backup file isn't valid JSON.", "err");
          return;
        }
        if (!window.eli.backup || typeof window.eli.backup.importAll !== "function") {
          if (typeof showToast === "function") showToast("Backup API missing — kernel reload needed.", "err");
          return;
        }
        if (typeof showToast === "function") showToast("⏳ Restoring backup…", "info");
        eli.events.safeAsync(window.eli.backup.importAll(parsed), "refresh_eli.import")
          .then(function (stats) {
            if (typeof showToast === "function") {
              showToast("✅ Restored · " + stats.stores + " stores, " + stats.rows + " rows. Reloading…", "ok");
            }
            setTimeout(function () { location.reload(); }, 800);
          })
          .catch(function (err) {
            if (typeof showToast === "function") showToast("Restore failed: " + (err && err.message), "err");
          });
      };
      reader.onerror = function () {
        if (typeof showToast === "function") showToast("Couldn't read file.", "err");
      };
      reader.readAsText(f);
    };
    document.body.appendChild(input);
    input.click();
    setTimeout(function () { if (input.parentNode) input.parentNode.removeChild(input); }, 5000);
  }

  // ─── Render the panel ──────────────────────────────────────────────
  function _render() {
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) {
      if (typeof showToast === "function") showToast("Dashboard root missing", "err");
      return;
    }
    mount.innerHTML = "";
    var root = document.createElement("div");
    root.className = "_eli3_re_root";
    root.innerHTML =
      '<div class="_eli3_re_bar">' +
        '<button class="_eli3_re_back" title="Back">←</button>' +
        '<div class="_eli3_re_title">🔄 Refresh ELI</div>' +
      '</div>' +
      '<div class="_eli3_re_body">' +
        '<p class="_eli3_re_intro">Round-trip the install so you can test ELI in a first-run state ' +
          'without losing stats, trophies, or settings.</p>' +
        // STEP 1
        '<div class="_eli3_re_card">' +
          '<div class="_eli3_re_step">STEP 1</div>' +
          '<div class="_eli3_re_card_title">Copy backup to clipboard</div>' +
          '<div class="_eli3_re_card_desc">Bundles stats, trophies, settings, templates, requesters, and other user state ' +
            'into a JSON blob and copies it to your clipboard. Paste into Notepad / VS Code / etc. and save as ' +
            '<code>eli-backup-&lt;stamp&gt;.json</code> before continuing. Tools are excluded — they re-download from CDN after wipe.</div>' +
          '<button class="_eli3_re_btn _eli3_re_btn_export" data-refresh-act="export">' +
            '<span class="_eli3_re_icon">📋</span> Copy backup to clipboard' +
          '</button>' +
        '</div>' +
        // STEP 2
        '<div class="_eli3_re_card _eli3_re_card_danger">' +
          '<div class="_eli3_re_step">STEP 2</div>' +
          '<div class="_eli3_re_card_title">Wipe &amp; reload</div>' +
          '<div class="_eli3_re_card_desc">Clears every IDB store + v2 localStorage key + Office doc-settings ' +
            'cache. Reloads the taskpane. ELI boots as if first-run.</div>' +
          '<button class="_eli3_re_btn _eli3_re_btn_danger" data-refresh-act="wipe">' +
            '<span class="_eli3_re_icon">🗑</span> Wipe &amp; Reload' +
          '</button>' +
        '</div>' +
        // STEP 3
        '<div class="_eli3_re_card">' +
          '<div class="_eli3_re_step">STEP 3 (OPTIONAL)</div>' +
          '<div class="_eli3_re_card_title">Restore from backup</div>' +
          '<div class="_eli3_re_card_desc">After the reload + re-onboarding, pick the JSON file from Step 1 ' +
            'to restore stats, trophies, settings, and any saved templates.</div>' +
          '<button class="_eli3_re_btn _eli3_re_btn_secondary" data-refresh-act="import">' +
            '<span class="_eli3_re_icon">📥</span> Import Backup' +
          '</button>' +
        '</div>' +
      '</div>';
    var back = root.querySelector("._eli3_re_back");
    if (back) back.onclick = function () {
      if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
    };
    root.querySelector("[data-refresh-act='export']").onclick = _exportEverything;
    root.querySelector("[data-refresh-act='wipe']").onclick   = _wipeAndReload;
    root.querySelector("[data-refresh-act='import']").onclick = _importBackup;
    mount.appendChild(root);
  }

  eli.register({
    tile: { app_refresh_eli: _render },
    refresh_eli: { open: _render },
  });

  eli.log.event("tool", "refresh_eli_initialized", {});
}

jsonTools.css:
/* tools/refresh_eli/style.css — three-card panel for export / wipe /
 * import. Mounts on the dashboard root (same takeover pattern as
 * tool_manager + eli_settings). */

._eli3_re_root {
  display: flex; flex-direction: column;
  width: 100%; height: 100%;
  box-sizing: border-box;
  background: #fff;
  overflow: hidden;
}
/* Kill the parent overflow when the panel is mounted — otherwise the
 * inner card list grows two scrollbars (host + this panel). Matches
 * the tool_manager pattern. */
body:has(._eli3_re_root) #output,
body:has(._eli3_re_root) #_eli3_dashboard_root {
  overflow: hidden !important;
}

._eli3_re_bar {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 10px;
  padding: 12px 14px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  border-bottom: 3px solid #c9a227;
}
._eli3_re_back {
  background: none; border: none; cursor: pointer;
  font: 400 22px/1 'Inter', sans-serif; color: #cbd5e1;
  padding: 0 4px;
  transition: color 0.15s;
}
._eli3_re_back:hover { color: #f2d866; }
._eli3_re_title {
  font: 800 16px/1.2 'Georgia', serif;
  color: #fff;
  letter-spacing: 0.2px;
  flex: 1;
}

._eli3_re_body {
  flex: 1; overflow-y: auto;
  padding: 16px 18px 24px;
  background: #f8fafc;
}
._eli3_re_intro {
  font: 500 12.5px/1.5 'Inter', sans-serif;
  color: #475569;
  margin: 0 0 14px;
}

._eli3_re_card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #1565c0;
  padding: 14px 16px;
  margin-bottom: 12px;
}
._eli3_re_card_danger {
  border-left-color: #dc2626;
  background: linear-gradient(135deg, #fff 0%, #fef2f2 100%);
}
._eli3_re_step {
  font: 800 9.5px/1 'Inter', sans-serif;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: #64748b;
  margin-bottom: 4px;
}
._eli3_re_card_danger ._eli3_re_step { color: #b91c1c; }
._eli3_re_card_title {
  font: 800 15px/1.2 'Inter', sans-serif;
  color: #0f172a;
  margin-bottom: 6px;
}
._eli3_re_card_desc {
  font: 400 12px/1.5 'Inter', sans-serif;
  color: #475569;
  margin-bottom: 10px;
}

._eli3_re_btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  font: 800 11px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  padding: 10px 16px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  cursor: pointer;
  transition: transform .12s, box-shadow .12s;
}
._eli3_re_btn:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 4px 10px rgba(21,101,192,0.3);
}
._eli3_re_btn:disabled {
  opacity: 0.55;
  cursor: wait;
}
._eli3_re_btn_danger {
  background: linear-gradient(135deg, #dc2626 0%, #991b1b 100%);
  border-color: #991b1b;
}
._eli3_re_btn_danger:hover:not(:disabled) {
  box-shadow: 0 4px 10px rgba(220,38,38,0.3);
}
._eli3_re_btn_secondary {
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  color: #475569;
  border: 1px solid #cbd5e1;
}
._eli3_re_btn_secondary:hover:not(:disabled) {
  background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%);
  color: #1565c0;
  border-color: #90caf9;
}
._eli3_re_icon { font-size: 14px; }
